// openclaw.config.json
{
  "cron": [
    {
      "schedule": "0 9 * * *",
      "action": "Triage my inbox by priority",
      "channel": "whatsapp"
    },
    {
      "schedule": "0 18 * * 5",
      "action": "Generate weekly summary",
      "channel": "slack"
    }
  ],
  "webhooks": {
    "github-push": "Review the latest commit"
  }
}

// Enable agent-to-agent communication
{
  "tools": {
    "agentToAgent": {
      "enabled": true,
      "allow": [
        "programmer",
        "reviewer",
        "tester"
      ]
    }
  }
}
// Coordinator spawns sessions per agent
// Work happens in parallel
// Results flow back automatically
